/// <summary>
///   Gets a journal and a voucher number.
/// </summary>
/// <returns>
///   A <c>Container</c> with a journal and voucher number.
/// </returns>
protected container getNumAndVoucher()
{
    METSalesTable       metSalesTable =  METSalesTable::findByRefRecId(salesTable.RecId);
    METSalesOrderTypes  metSalesOrderTypes = METSalesOrderTypes::find(salesTable.METSalesOrderType);

    next getNumAndVoucher();

    if (salesTable.SalesType == SalesType::Sales
            && strLen(metSalesTable.InvoiceNumber) > 0
            && metSalesOrderTypes.ExternalInvoiceNumber == NoYes::Yes)
    {
        journalNumber = metSalesTable.InvoiceNumber;
    }

    return [journalNumber, voucher];
}
